const months = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

// decap writes each data file as an object with one top-level key
function readData(name, key) {
	let data = JSON.parse(fs.readFileSync(path.join(root, 'data', name), 'utf8'));
	return key == undefined ? data : data[key];
}

const siteContent = readData('content.json');

function escapeHtml(text) {
	return text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function inlineMarkdown(text) {
	return escapeHtml(text)
		.replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, '<a href="$2" target="_blank">$1</a>')
		.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
		.replace(/(^|[^*])\*([^*\n]+)\*/g, '$1<em>$2</em>');
}

// just enough markdown for the rich text fields decap writes into content.json:
// headings, bold, italic, links, bulleted and numbered lists, paragraphs
function renderMarkdown(text, indent) {
	if (text == undefined || text.trim() == '') {
		return '';
	}
	let pad = '\t'.repeat(indent);
	let blocks = [];
	for (let block of text.trim().split(/\n\s*\n/)) {
		let lines = block.split('\n').map(line => line.trim()).filter(line => line != '');
		if (lines.length == 0) {
			continue;
		}
		let heading = lines[0].match(/^(#{2,4})\s+(.*)$/);
		if (heading != null && lines.length == 1) {
			let level = heading[1].length;
			blocks.push(`${pad}<h${level}>${inlineMarkdown(heading[2])}</h${level}>`);
			continue;
		}
		if (lines.every(line => /^[-*]\s+/.test(line))) {
			let items = lines.map(line => `${pad}\t<li>${inlineMarkdown(line.replace(/^[-*]\s+/, ''))}</li>`).join('\n');
			blocks.push(`${pad}<ul>\n${items}\n${pad}</ul>`);
			continue;
		}
		if (lines.every(line => /^\d+\.\s+/.test(line))) {
			let items = lines.map(line => `${pad}\t<li>${inlineMarkdown(line.replace(/^\d+\.\s+/, ''))}</li>`).join('\n');
			blocks.push(`${pad}<ol>\n${items}\n${pad}</ol>`);
			continue;
		}
		blocks.push(`${pad}<p>\n${pad}\t${inlineMarkdown(lines.join(' '))}\n${pad}</p>`);
	}
	return blocks.join('\n');
}

function formatDate(date) {
	let [year, month, day] = date.split('-').map(Number);
	return `${months[month - 1]} ${day}, ${year}`;
}

function formatLink(url) {
	return url.replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/$/, '');
}

