// calendar
function sortEvents(events) {
	return events.slice().sort((a, b) => {
		if (a.date != b.date) {
			return a.date < b.date ? -1 : 1;
		}
		if (!a.time) {
			return -1;
		}
		if (!b.time) {
			return 1;
		}
		return a.time < b.time ? -1 : 1;
	});
}

