// bulletin board
function sortPosts(posts) {
	return posts.slice().sort((a, b) => a.date < b.date ? 1 : -1);
}

function boardPost(post) {
	let body = !post.image ? `\t\t\t\t\t<div class="board-item-text">
\t\t\t\t\t\t<h2>${post.heading}</h2>
${post.text.map(text => `\t\t\t\t\t\t<p>
\t\t\t\t\t\t\t${text}
\t\t\t\t\t\t</p>`).join('\n')}
\t\t\t\t\t</div>` : `\t\t\t\t\t<div class="board-item-image">
\t\t\t\t\t\t<img src="${post.image}">
\t\t\t\t\t</div>`;
	let caption = post.permanent ? [] : [`\t\t\t\t\t\t<em>Posted on ${formatDate(post.date)} by ${post.name}.</em>`];
	if (post.contact) {
		caption.push(`\t\t\t\t\t\t<strong>Contact:</strong> <a href="mailto:${post.contact}">${post.contact}</a>`);
	}
	if (post.link) {
		caption.push(`\t\t\t\t\t\t<strong>More Information:</strong> <a href="${post.link}" target="_blank">${formatLink(post.link)}</a>`);
	}
	let figcaption = caption.length == 0 ? '' : `
\t\t\t\t\t<figcaption>
${caption.join('<br>\n')}
\t\t\t\t\t</figcaption>`;
	return `\t\t\t\t<figure class="board-item">
${body}${figcaption}
\t\t\t\t</figure>`;
}

