// templates
function buildHead(page) {
	let title = page.home ? page.title : `${page.name} | Oak Hill, Pawtucket, RI`;
	let head = page.head == undefined ? '' : `\n${page.head()}`;
	return `<!DOCTYPE html>
<html lang="en">
<head>
	<meta charset="UTF-8">
	<meta name="viewport" content="width=device-width, initial-scale=1.0">
	<title>${title}</title>
	<link rel="icon" type="png" href="/assets/meta/favicon-${page.primary}.png">
	<meta property="og:image" content="/assets/meta/opengraph.png">${head}
	<link rel="stylesheet" href="/style.css">
</head>
<body style="--primary: var(--${page.primary}); --secondary: var(--${page.secondary});">`;
}

function buildScripts(page) {
	let scripts = page.scripts == undefined ? [] : page.scripts;
	return scripts.concat(['/form.js', '/transition.js']).map(src => `	<script src="${src}"></script>`).join('\n');
}

function buildHome(page) {
	let links = pages.filter(item => !item.home).map(item => `			<a href="${item.url}" class="home-nav-link" style="--primary: var(--${item.primary}); --secondary: var(--${item.secondary});">
				${icon}
				<span>${item.name}</span>
			</a>`).join('\n');
	return `${buildHead(page)}
	<div class="home">
${homeMarquee()}
		<div class="home-logo">
			${logo}
		</div>
		<nav class="home-nav">
${links}
		</nav>
	</div>
	<button class="home-submit" type="button" onclick="openForm();">
		<span class="home-submit-icon">+</span>
		<span class="home-submit-text">Send us a photo!</span>
	</button>
${buildForm(page)}
${buildScripts(page)}
</body>
</html>
`;
}

function buildPage(page) {
	let links = pages.filter(item => !item.home).map(item => {
		let active = item.url == page.url ? ' data-active="1"' : '';
		return `				<a href="${item.url}" class="nav-link" style="--primary: var(--${item.primary}); --secondary: var(--${item.secondary});"${active}>
					${icon}
					<span>${item.name.replace(' ', ' <br>')}</span>
				</a>`;
	}).join('\n');
	let extra = page.extra == undefined ? '' : `\n${page.extra()}`;
	extra += `\n${buildForm(page)}`;
	let data = page.data == undefined ? '' : `\n${page.data()}`;
	return `${buildHead(page)}
	<div class="container">
		<nav class="nav">
			<a class="nav-logo" href="/">
				${logo}
			</a>
			<div class="nav-links">
${links}
			</div>
			<button class="nav-submit" type="button" onclick="openForm();">
				<span class="nav-submit-icon">+</span>
				<span class="nav-submit-text">${page.submit == undefined ? 'Contribute to this site!' : page.submit}</span>
			</button>
		</nav>
		<main class="content">
${page.content()}
		</main>
	</div>${extra}${data}
${buildScripts(page)}
</body>
</html>
`;
}

function build() {
	for (let page of pages) {
		let html = page.home ? buildHome(page) : buildPage(page);
		let file = path.join(root, page.path);
		fs.mkdirSync(path.dirname(file), {recursive: true});
		fs.writeFileSync(file, html);
		console.log(`built ${page.path}`);
	}
}

build();
